const list = document.querySelector('#devices');
const state = document.querySelector('#state');
const tpl = document.querySelector('#device-row');

function render(devices) {
  const frag = document.createDocumentFragment();
  for (const d of devices) {
    const row = tpl.content.cloneNode(true);
    const li = row.querySelector('li');
    li.dataset.id = d.id;
    li.classList.toggle('offline', !d.online);
    row.querySelector('.name').textContent = d.name;
    row.querySelector('.ip').textContent = d.ip;
    frag.append(row);
  }
  list.replaceChildren(frag);
}

async function load(url) {
  state.textContent = 'Loading…';
  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const devices = await res.json();
    render(devices);
    state.textContent = devices.length ? `${devices.length} devices` : 'No devices match.';
  } catch (err) {
    list.replaceChildren();
    state.textContent = `Could not load devices (${err.message}).`;
  }
  console.log(url, '->', state.textContent, list.children.length);
}

await load('/api/error');
